    max_diff = -1
    # Optimization: c = d+e. For a fixed c, we want to maximize d-e.
    # d-e = d - (c-d) = 2d - c. So we want the largest d such that d-e = d-(c-d) is maximized.
    # Since d <= 10000 and e >= 2025, we have c-d >= 2025 => d <= c-2025.
    # So d = min(10000, c-2025).
    # And we also need d >= 2025, so c-2025 >= 2025 => c >= 4050.
    # Also c = d+e <= 10000+10000 = 20000.
    for c in range(4050, 20001):
        d = min(10000, c - 2025)
        if d < 2025:
            continue
        e = c - d

        target_a = 2024 + d
        divisors_c = []
        for i in range(1, int(c**0.5) + 1):
            if c % i == 0:
                divisors_c.append(i)
                if i*i != c:
                    divisors_c.append(c // i)

        possible = True
        for g in divisors_c:
            if 2024 % g != 0 and target_a % g != 0:
                possible = False
                break

        if possible:
            max_diff = max(max_diff, d - e)
    return max_diff

