def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def check_factors(n, allowed_primes):
    factors = prime_factorization(n)
    for p in factors:
        if p not in allowed_primes:
            return False
    return True

